## Retro Arcade: Snake

### Direction and Snake

```xiom
enum Direction {
  Up;
  Down;
  Left;
  Right;
}

type Point {
  x: Int;
  y: Int;
}

type Snake {
  body: Vec[Point];
  direction: Direction;
}

fn create_snake() -> Snake {
  let mut body: Vec[Point] = Vec[Point].new();
  body.push(Point{ x: 5, y: 5 });
  body.push(Point{ x: 4, y: 5 });
  body.push(Point{ x: 3, y: 5 });
  Snake{ body: body, direction: Direction.Right }
}
```

### The Game World

```xiom
type GameWorld {
  width: Int;
  height: Int;
  snake: Snake;
  food: Point;
  score: Int;
  game_over: Bool;
}

fn spawn_food(world: &GameWorld) -> Point {
  let fx = random.range(0, world.width);
  let fy = random.range(0, world.height);

  let mut i = 0;
  while i < world.snake.body.len() {
    let seg = world.snake.body.get(i).unwrap();
    if seg.x == fx && seg.y == fy {
      fx = random.range(0, world.width);
      fy = random.range(0, world.height);
      i = 0;
    } else {
      i += 1;
    };
  };
  Point{ x: fx, y: fy }
}
```

### Moving the Snake

```xiom
fn move_snake(snake: &mut Snake) {
  let head = snake.body.get(0).unwrap();
  let new_head = match snake.direction {
    Direction.Up => Point{ x: head.x, y: head.y - 1 },
    Direction.Down => Point{ x: head.x, y: head.y + 1 },
    Direction.Left => Point{ x: head.x - 1, y: head.y },
    Direction.Right => Point{ x: head.x + 1, y: head.y },
  };

  let mut new_body: Vec[Point] = Vec[Point].new();
  new_body.push(new_head);

  let mut i = 0;
  while i < snake.body.len() - 1 {
    new_body.push(snake.body.get(i).unwrap());
    i += 1;
  };
  snake.body = new_body;
}
```

### Collision Detection

```xiom
fn check_collision(snake: &Snake, w: Int, h: Int) -> Bool {
  let head = snake.body.get(0).unwrap();

  if head.x < 0 || head.x >= w || head.y < 0 || head.y >= h {
    return true;
  };

  let mut i = 1;
  while i < snake.body.len() {
    let seg = snake.body.get(i).unwrap();
    if seg.x == head.x && seg.y == head.y { return true; };
    i += 1;
  };
  false
}

fn check_food(snake: &Snake, food: &Point) -> Bool {
  let head = snake.body.get(0).unwrap();
  head.x == food.x && head.y == food.y
}

fn grow_snake(snake: &mut Snake) {
  let tail = snake.body.get(snake.body.len() - 1).unwrap();
  snake.body.push(Point{ x: tail.x, y: tail.y });
}
```

### Rendering the Grid

```xiom
fn render(world: &GameWorld) {
  let mut y = 0;
  while y < world.height {
    let mut line: Str = "";
    let mut x = 0;
    while x < world.width {
      let mut ch = ".";

      if x == world.food.x && y == world.food.y { ch = "@"; }
      else {
        let mut i = 0;
        while i < world.snake.body.len() {
          let seg = world.snake.body.get(i).unwrap();
          if seg.x == x && seg.y == y {
            ch = if i == 0 { "O" } else { "o" };
          };
          i += 1;
        };
      };

      line = line + ch + " ";
      x += 1;
    };
    io.println(line);
    y += 1;
  };
}
```

### The Game Loop

```xiom
fn update(world: &mut GameWorld) {
  move_snake(&mut world.snake);

  if check_food(&world.snake, &world.food) {
    grow_snake(&mut world.snake);
    world.score += 10;
    world.food = spawn_food(world);
  };

  if check_collision(&world.snake, world.width, world.height) {
    world.game_over = true;
  };
}

fn simulate_moves(world: &mut GameWorld, moves: &Vec[Direction]) {
  let mut i = 0;
  while i < moves.len() && !world.game_over {
    world.snake.direction = moves.get(i).unwrap();
    update(world);
    render(world);
    i += 1;
  };
}
```

