use xiom.io;
enum Direction {
  Up,
  Down,
  Left,
  Right,
}

type Pos = { x: Int; y: Int; }

type SnakeGame = {
  body: Vec[Pos];
  dir: Direction;
  food: Pos;
  score: Int;
  over: Bool;
}

fn create_game() -> SnakeGame {
  var body: Vec[Pos] = Vec[Pos].new();
  body.push(Pos{ x: 5, y: 5 });
  body.push(Pos{ x: 4, y: 5 });
  body.push(Pos{ x: 3, y: 5 });

  SnakeGame{
    body: body,
    dir: Direction.Right,
    food: Pos{ x: 8, y: 5 },
    score: 0,
    over: false
  }
}

fn move_snake(game: &mut SnakeGame) {
  let head = game.body.get(0).unwrap();
  let new_head = match game.dir {
    Direction.Up => Pos{ x: head.x, y: head.y - 1 },
    Direction.Down => Pos{ x: head.x, y: head.y + 1 },
    Direction.Left => Pos{ x: head.x - 1, y: head.y },
    Direction.Right => Pos{ x: head.x + 1, y: head.y },
  };

  var new_body: Vec[Pos] = Vec[Pos].new();
  new_body.push(new_head);
  var i = 0;
  while i < game.body.len() - 1 {
    new_body.push(game.body.get(i).unwrap());
    i = i + 1;
  };
  game.body = new_body;
}

fn check_hit(game: &SnakeGame, w: Int, h: Int) -> Bool {
  let head = game.body.get(0).unwrap();
  if head.x < 0 || head.x >= w || head.y < 0 || head.y >= h { return true; };
  var i = 1;
  while i < game.body.len() {
    let seg = game.body.get(i).unwrap();
    if seg.x == head.x && seg.y == head.y { return true; };
    i = i + 1;
  };
  false
}

fn render(game: &SnakeGame, w: Int, h: Int) {
  var y = 0;
  while y < h {
    var line: Str = "";
    var x = 0;
    while x < w {
      var ch = ".";
      if x == game.food.x && y == game.food.y { ch = "@"; }
      else {
        var i = 0;
        while i < game.body.len() {
          let seg = game.body.get(i).unwrap();
          if seg.x == x && seg.y == y {
            ch = if i == 0 { "O" } else { "o" };
          };
          i = i + 1;
        };
      };
      line = line + ch + " ";
      x = x + 1;
    };
    io.println(line.to_str());
    y = y + 1;
  };
}

fn main() -> Int {
  var game = create_game();
  let w = 15;
  let h = 10;

  render(&game, w, h);
  move_snake(&game);
  move_snake(&game);
  move_snake(&game);
  io.println("After 3 moves right:");
  render(&game, w, h);

  game.dir = Direction.Down;
  move_snake(&game);
  move_snake(&game);
  io.println("After 2 moves down:");
  render(&game, w, h);

  io.println(game.score.to_str());
  io.println(game.over.to_str());
  return 0;
}
